};


/********************************************** 
 * 함수명   : ins_search
 * 설명       : ELS_DLS 마스터  목록 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    /**
     * SrM-000243255 
     */
    if (!scwin.checkSearchCondition()) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_SISUDATE, edt_EISUDATE) == false) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_SDATE, edt_EDATE) == false) {
        return false;
    }
    dts_detail.removeAll();
    $c.stf.setObjectValue(cmb_cb_p_group, "");
    $c.stf.setObjectValue(cmb_cb_p_attr_1, "");
    $c.stf.setObjectValue(cmb_cb_p_attr_2, "");
    $c.stf.setObjectValue(cmb_cb_p_attr_3, "");
    $c.stf.setObjectValue(cmb_cb_p_attr_4, "");

    // 조회버튼 비활성.
    fn_SetDisableSelectBtn(btn_search, true);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=STDCDSTKINFO_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcdelsdls.select.listStdCdElsDlsInfoInquiry" + "&{P}STD_CD=" + txb_pSTD_CD.getValue() + "&{P}ISU_KOR_NM=" + txb_pISU_KOR_NM.getValue() + "&{P}ISUR_CD=" + txb_pISUR_CD.getValue() + "&{P}ACTIV_TP_CD=" + $c.stf.getObjectValue(cmb_pACTIV_YN) + "&{P}ELS_DLS_TP_CD=" + $c.stf.getObjectValue(cmb_pELS_DLS_TP_CD) + "&{P}SISUDATE=" + edt_SISUDATE.getValue() + "&{P}EISUDATE=" + edt_EISUDATE.getValue() + "&{P}SDATE=" + edt_SDATE.getValue() + "&{P}EDATE=" + edt_EDATE.getValue();
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

};


/********************************************** 
 * 함수명   : checkSearchCondition
 * 설명      : SrM-000243255  조회조건을 체크
 *                표준코드, 한글종목명, 발행기관코드에 값이 입력 안되었을 경우 
 *                날짜 조건은 필수로 입력되도록.. 날짜 입력가능 범위는 5년..
 ***********************************************/
scwin.checkSearchCondition = function() {
    var sStdCd = $c.stf.getObjectValue(txb_pSTD_CD);
    var sIsuKorNm = $c.stf.getObjectValue(txb_pISU_KOR_NM);
    var sIsurCd = $c.stf.getObjectValue(txb_pISUR_CD);
    var sIsuDateFrom = $c.stf.getObjectValue(edt_SISUDATE); //발행일(from)
    var sIsuDateTo = $c.stf.getObjectValue(edt_EISUDATE); //발행일(to)
    var sSDateFrom = $c.stf.getObjectValue(edt_SDATE); //코드부여일(from)
    var sSDateTo = $c.stf.getObjectValue(edt_EDATE); //코드부여일(to)

    if (sStdCd == "" && sIsuKorNm == "" && sIsurCd == "") {
        if (sIsuDateFrom == "" && sIsuDateTo == "" && sSDateFrom == "" && sSDateTo == "") {
            var msg = "조회조건을 최소 1개 이상 입력하세요.\n\n" + "[표준코드, 한글종목명, 발행기관명(코드)] 중 1개 이상의 조건을 입력하거나, \n" + "[발행일 또는 코드부여일]의 검색기간을 5년 이내로 입력하세요.";
            $c.win.alert(msg);
            return false;
        }

        // 발행일 체크
        if (sIsuDateFrom != "" && sIsuDateTo != "") {
            if (eval($c.ut.cGetPlusYear(sIsuDateFrom, 5)) < eval(sIsuDateTo)) {
                $c.win.alert("발행일의 검색기간은 5년 이내로 입력하세요.");
                edt_SISUDATE.focus();
                return false;
            }
        } else if (sIsuDateFrom != "" || sIsuDateTo != "") {
            $c.win.alert("발행일의 검색기간은 5년 이내로 입력하세요.");
            if (sIsuDateFrom == "") {
                edt_SISUDATE.focus();
            } else {
                edt_EISUDATE.focus();
            }
            return false;
        }

        // 코드부여일 체크
        if (sSDateFrom != "" && sSDateTo != "") {
            if (eval($c.ut.cGetPlusYear(sSDateFrom, 5)) < eval(sSDateTo)) {
                $c.win.alert("코드부여일의 검색기간은 5년 이내로 입력하세요.");
                edt_SDATE.focus();
                return false;
            }
        } else if (sSDateFrom != "" || sSDateTo != "") {
            $c.win.alert("코드부여일의 검색기간은 5년 이내로 입력하세요.");
            if (sSDateFrom == "") {
                edt_SDATE.focus();
            } else {
                edt_EDATE.focus();
            }
            return false;
        }
    }
    return true;
};


/********************************************** 
 * 함수명   : ins_detail
 * 설명       : elsdls 상세 조회한다.
 ***********************************************/
scwin.ins_detail = function(STD_CD) {
    dts_detail.removeAll();
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ELSDLS_DETAIL_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcdelsdls.select.readStdCdElsDlsInfoView" + "&{P}STD_CD=" + STD_CD;
    dts_detail.DataID = encodeURI(url);
    dts_detail.reset();
};


/********************************************** 
 * 함수명   : fn_formCheck
 * 설명       : 폼을 체크한다.
 ***********************************************/
scwin.fn_formCheck = function() {
    if (txb_ISUR_CD.getValue() == "" || txb_ISUR_CD.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관코드"));
        txb_ISUR_CD.focus();
