    if (!$c.stf.checkMaxLength(txb_UNQ_ISU_ENG_NM, 20, "영문고유명")) {
        txb_UNQ_ISU_ENG_NM.focus();
        return false;
    }

    //날짜포맷 체크
    if (fn_CheckDateObj(edt_ISU_DD, "발행일")) return false;
    if (fn_CheckDateObj(edt_EXP_DD, "만기일")) return false;
    if (cmb_RGHT_TP_CD.getText() == "" || cmb_RGHT_TP_CD.text.indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "권리유형"));
        cmb_RGHT_TP_CD.focus();
        return false;
    }

    // 원금비보장일떄 100이상 입력시 에러 
    if ($c.stf.getObjectValue(rdo_PRINC_GRT_YN) == "N") {
        if (eval($c.stf.getObjectValue(edt_PRINC_GRT_RT)) >= 100) {
