/********************************************** 
 * 함수명   : fn_Change_cfi
 * 설명       : cfi 변경 설정 - 채권과 동일 .....
 ***********************************************/
scwin.fn_Change_cfi = function() {
    // Cfi의 콤보 박스를 변경할 경우....
    var cfi = "";
    cfi = "D";
    if ($c.stf.getObjectValue(cmb_cb_p_group) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_group);
    if ($c.stf.getObjectValue(cmb_cb_p_attr_1) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_1);
    if ($c.stf.getObjectValue(cmb_cb_p_attr_2) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_2);
    if ($c.stf.getObjectValue(cmb_cb_p_attr_3) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_3);
    if ($c.stf.getObjectValue(cmb_cb_p_attr_4) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_4);
    txb_CFI_CD.setValue(cfi); // cfi 설정

};


/********************************************** 
 * 함수명   : fn_set_Change
 * 설명       :  상세 조회시 CFI 상세 설정 
 ***********************************************/
scwin.fn_set_Change = function(str_cfi) {
    if (str_cfi == "") return;
    $c.stf.setObjectValue(cmb_cb_p_group, str_cfi.substring(1, 2));
    $c.stf.setObjectValue(cmb_cb_p_attr_1, str_cfi.substring(2, 3));
    $c.stf.setObjectValue(cmb_cb_p_attr_2, str_cfi.substring(3, 4));
    $c.stf.setObjectValue(cmb_cb_p_attr_3, str_cfi.substring(4, 5));
    $c.stf.setObjectValue(cmb_cb_p_attr_4, str_cfi.substring(5, 6));
};
scwin.arrPar = new Array();
/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달 값을 정의한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue();
    scwin.arrPar[1] = txb_param2.getValue();
};



/********************************************** 
 * 함수명   : ins_modify
 * 설명       : elsdls 표준코드  수정한다.
 ***********************************************/
scwin.ins_modify = function() {
    if (!confirm("정보분배시스템으로 수정내역이 전송됩니다.")) {
        return;
    }
    dts_detail.setCellData(dts_detail.getRowPosition(), "CRUDSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    trs_modify.Action = "/StdCdBndElsDlsInfoAction.do?method=modifyStdCdBndElsDlsInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_modify.KeyName = "toinb_dataid4";
    trs_modify.KeyValue = "JSP(O:pReturnOut=dts_Rst,I:pInputMaster=dts_detail)";
    trs_modify.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_modify.Post();
};


/********************************************** 
 * 함수명   : ins_remove
 * 설명       : elsdls 삭제처리한다.
 ***********************************************/
scwin.ins_remove = function() {

    //dts_Delete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Delete.insertRow();
    dts_Delete.setCellData(1, "STD_CD", txb_STD_CD.getValue());
    dts_Delete.setCellData(1, "ISU_NM", txb_ISU_NM.getValue());
    dts_Delete.setCellData(1, "CHG_RSN", txb_DEL_RSN.getValue());
    trs_remove.Action = "/StdCdBndElsDlsInfoAction.do?method=removeStdCdBndElsDlsInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    trs_remove.KeyName = "toinb_dataid4";
    trs_remove.KeyValue = "JSP(I:pInput=dts_Delete)";
    trs_remove.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_remove.Post();
};



/********************************************** 
 * 함수명   : fn_BND_ISU_METHD_CD
 * 설명       : 발행방법 정의한다. 100 : 공모-간접발행, 010 : 공모-직접발행, 001 : 사모
 ***********************************************/
scwin.fn_BND_ISU_METHD_CD = function() {
    var BND_ISU_METHD_CD1 = $c.stf.getObjectValue(ckb_BND_ISU_METHD_CD1);
    var BND_ISU_METHD_CD2 = $c.stf.getObjectValue(ckb_BND_ISU_METHD_CD2);
    var BND_ISU_METHD_CD3 = $c.stf.getObjectValue(ckb_BND_ISU_METHD_CD3);
    if (BND_ISU_METHD_CD1 == "Y") {
        BND_ISU_METHD_CD1 = "1";
    } else {
        BND_ISU_METHD_CD1 = "0";
    }
    if (BND_ISU_METHD_CD2 == "Y") {
        BND_ISU_METHD_CD2 = "1";
    } else {
        BND_ISU_METHD_CD2 = "0";
    }
    if (BND_ISU_METHD_CD3 == "Y") {
        BND_ISU_METHD_CD3 = "1";
    } else {
        BND_ISU_METHD_CD3 = "0";
    }
    $c.stf.setObjectValue(txb_BND_ISU_METHD_CD, BND_ISU_METHD_CD1 + BND_ISU_METHD_CD2 + BND_ISU_METHD_CD3);
};


/********************************************** 
 * 함수명   : fn_set_BND_ISU_METHD_CD
 * 설명       : 발행방법 정의한다. 100 : 공모-간접발행, 010 : 공모-직접발행, 001 : 사모
 ***********************************************/
scwin.fn_set_BND_ISU_METHD_CD = function() {
    var BND_ISU_METHD_CD = $c.stf.getObjectValue(txb_BND_ISU_METHD_CD);
    $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD1, "N");
    $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD2, "N");
    $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD3, "N");
    if (BND_ISU_METHD_CD == "") return;
    var BND_ISU_METHD_CD1 = BND_ISU_METHD_CD.substring(0, 1);
    var BND_ISU_METHD_CD2 = BND_ISU_METHD_CD.substring(1, 2);
    var BND_ISU_METHD_CD3 = BND_ISU_METHD_CD.substring(2, 3);
    if (BND_ISU_METHD_CD1 == "1") {
        $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD1, "Y");
    } else {
        $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD1, "N");
    }
    if (BND_ISU_METHD_CD2 == "1") {
        $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD2, "Y");
    } else {
        $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD2, "N");
    }
    if (BND_ISU_METHD_CD3 == "1") {
        $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD3, "Y");
    } else {
        $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD3, "N");
    }
};





/********************************************** 
 * 함수명   : fn_setBndView
 * 설명       :  elsdls 상세화면을 정의한다.
 ***********************************************/
scwin.fn_setBndView = function(SIMSA_YN, LIST_STAT_CD) {
    if (LIST_STAT_CD == "N" && SIMSA_YN == "Y") {
        $c.win.alert(" 해당종목은 신규상장심사종목입니다. \n" + " 수정후에는 반드시 채권심사종목정보도 수정이 되도록 채권상장팀에 통보를 하셔야 됩니다.");
    } else if (LIST_STAT_CD == "Y") {
        //alert(" 상장채권은 수정할 수 없습니다 \n" + " 채권상장팀과 협의하시기 바랍니다");
        btn_modify.setDisabled(true);
        btn_modify.src = "../img/ins/btn_modify_d.gif";
        btn_delete.setDisabled(true);
        btn_delete.src = "../img/ins/btn_delete_d.gif";
        btn_clearPwd.setDisabled(true);
        btn_clearPwd.src = "../img/ins/btn_clearPwd_d.gif";
    } else {
        btn_modify.setDisabled(false);
        btn_modify.src = "../img/ins/btn_modify.gif";
        btn_delete.setDisabled(false);
        btn_delete.src = "../img/ins/btn_delete.gif";
        btn_clearPwd.setDisabled(false);
        btn_clearPwd.src = "../img/ins/btn_clearPwd.gif";
    }
};
