scwin.dts_detail_OnLoadCompleted = function(rowcount) {
    var ACTIV_YN = dts_List.getCellData(dts_List.rowpositon, "ACTIV_YN"); // 발행기관 활성여부
    //alert("ACTIV_YN " +ACTIV_YN);
    if (ACTIV_YN == "N") {
        $c.win.alert("해당회사는 비활성 발행기관입니다.");
    }


    //	alert(getObjectValue(ckb_NPARVALSTK_YN));


    if (rowcount > 0) {
        //alert( dts_detail.NameValue(dts_detail.rowpositon,"MAX_YD"));
        var str_cfi = dts_detail.getCellData(dts_detail.rowpositon, "CFI_CD");
        scwin.fn_set_Change(str_cfi);
        fn_CtrlBtn_temp("update");

        // 20140114 심사,상장여부 체크 추가 
        var SIMSA_YN = dts_detail.getCellData(dts_detail.rowpositon, "SIMSA_YN");
        var LIST_STAT_CD = dts_detail.getCellData(dts_detail.rowpositon, "LIST_STAT_CD");
        //	SIMSA_YN = "Y";
        //	LIST_STAT_CD = "N";

        scwin.fn_setBndView(SIMSA_YN, LIST_STAT_CD);
    } else {
        scwin.fn_set_Change("");
        fn_CtrlBtn_temp("no_data");
    }
    scwin.fn_set_BND_ISU_METHD_CD();
};
