scwin.dts_FNC_ULY_TP_CD_OnLoadCompleted = function(rowcount) {
    /*
		0	스왑
1	주식
2	주식바스켓
3	주가지수
4	상품
5	금리
6	통화
7	옵션
8	선물
9	기타
*/
    for (var i = dts_FNC_ULY_TP_CD.getTotalRow(); i > 0; i--) {
        if (dts_FNC_ULY_TP_CD.getCellData(i, "VALUE") == "0" ||
            dts_FNC_ULY_TP_CD.getCellData(i, "VALUE") == "7" ||
            dts_FNC_ULY_TP_CD.getCellData(i, "VALUE") == "8") {
            $c.cp.removeRow(dts_FNC_ULY_TP_CD, i);
        }
    }
};
