scwin.cmb_ELS_DLS_TP_CD_OnSelChange = function() {
    var ELS_DLS_TP_CD = $c.stf.getObjectValue(cmb_ELS_DLS_TP_CD);
    /*
    els dls 선택시 원금비보장 rdo_PRINC_GRT_YN , 원금보장은 비활성 edt_PRINC_GRT_RT
    */
    if (ELS_DLS_TP_CD == "1" || ELS_DLS_TP_CD == "2") {
        $c.stf.setObjectValue(rdo_PRINC_GRT_YN, "N");
        $c.stf.setObjectValue(edt_PRINC_GRT_RT, "");
    }
    if (ELS_DLS_TP_CD == "1" || ELS_DLS_TP_CD == "3") {
        $c.stf.setObjectValue(txb_BND_CLSS_CD, "116600");
        $c.stf.setObjectValue(txb_BND_CLSS_NM, "ELS/ELB");
    } else if (ELS_DLS_TP_CD == "2" || ELS_DLS_TP_CD == "4") {
        $c.stf.setObjectValue(txb_BND_CLSS_CD, "116700");
        $c.stf.setObjectValue(txb_BND_CLSS_NM, "DLS/DLB");
    }
