scwin.dts_detail_OnColumnChanged = function(row, colid) {
    if (colid == "ISU_DD") {
        var ISU_DD = $c.stf.getObjectValue(edt_ISU_DD);
        var ISU_DD2 = dts_detail.getCellData(dts_detail.getRowPosition(), "ISU_DD2");
        if (ISU_DD == "") return;
        if (ISU_DD2 == "") return;
        if (parseInt(ISU_DD) < 20200901) {
            $c.win.alert("2020년 9월 1일 이전으로 변경 할 수 없습니다.");
            $c.stf.setObjectValue(edt_ISU_DD, ISU_DD2);
            dts_detail.setCellData(dts_detail.getRowPosition(), "ISU_DD", ISU_DD2);
        }
    }
};
